<template><section class="ops-panel"><div class="ops-toolbar"><div><h2>异常用量复核</h2><p class="ops-muted">调用用量尚未确认时保留预占。仅凭供应商查询或账单证据填写实际用量，不自动认定为零消费。</p></div><el-button size="small" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-table :data="rows" v-loading="loading"><el-table-column prop="createdAt" label="时间" min-width="160" /><el-table-column prop="modelId" label="模型" min-width="160" /><el-table-column prop="workspaceId" label="工作空间" min-width="150" /><el-table-column prop="reservedAmount" label="预占（元）" width="130" /><el-table-column prop="providerRequestId" label="供应商请求 ID" min-width="180" /><el-table-column label="操作" width="100"><template slot-scope="s"><el-button type="text" @click="open(s.row)">核对用量</el-button></template></el-table-column></el-table><el-pagination :current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="changePage" /><el-dialog title="记录供应商用量证据" :visible.sync="visible" width="min(580px,94vw)" :close-on-click-modal="false"><el-form label-width="120px"><el-form-item label="调用记录">{{ form.id }}</el-form-item><el-form-item label="供应商请求 ID"><el-input v-model="form.providerRequestId" maxlength="200" /></el-form-item><el-form-item label="证据引用"><el-input v-model="form.evidenceRef" placeholder="可追溯的账单记录、核对工单编号" maxlength="500" /></el-form-item><el-form-item label="实际用量"><el-input v-model="form.usageText" type="textarea" :rows="6" placeholder='{"input_tokens":"供应商确认值","output_tokens":"供应商确认值"}' /><p class="ops-muted">使用当前费率要求的计量字段。值为非负十进制字符串；语音时长使用毫秒。不得填写猜测值。</p></el-form-item></el-form><el-alert v-if="saveError" :title="saveError" type="error" :closable="false" /><span slot="footer"><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">按证据结算</el-button></span></el-dialog></section></template>
<script>
import { platformRequest } from '@/apis/platform';
import { newOperationId } from '@/utils/allowance';
export default {data(){return{rows:[],page:1,total:0,loading:false,error:'',visible:false,busy:false,saveError:'',form:{}};},created(){this.load();},methods:{async load(){this.loading=true;this.error='';try{const result=await platformRequest('GET','/ops/platform/reservations/review',{page:this.page,limit:20});this.rows=result.list||[];this.total=result.total||0;}catch(error){this.error=error.message;}finally{this.loading=false;}},changePage(page){this.page=page;this.load();},open(row){this.form={id:row.id,requestId:newOperationId(),providerRequestId:row.providerRequestId||'',evidenceRef:'',usageText:''};this.saveError='';this.visible=true;},async save(){if(this.busy)return;let usage;try{usage=JSON.parse(this.form.usageText);if(!usage||Array.isArray(usage)||typeof usage!=='object'||!Object.keys(usage).length||Object.values(usage).some(value=>typeof value!=='string'||!/^\d+(\.\d+)?$/.test(value)))throw new Error();}catch(_){this.saveError='请填写 JSON 对象，用量值必须为非负十进制字符串';return;}if(!this.form.providerRequestId.trim()||!this.form.evidenceRef.trim()){this.saveError='请填写供应商请求 ID 与证据引用';return;}this.busy=true;this.saveError='';try{await platformRequest('POST',`/ops/platform/reservations/${encodeURIComponent(this.form.id)}/resolve`,{requestId:this.form.requestId,evidenceRef:this.form.evidenceRef.trim(),providerRequestId:this.form.providerRequestId.trim(),usage});this.visible=false;await this.load();}catch(error){this.saveError=error.message;}finally{this.busy=false;}}}};
</script>
